-- 1356: Blog post -- "Generative AI for Social Media Marketing: From Empty Calendar to Campaign That Performs".
-- Focus: GenAI across the social workflow -- platform choice, a month from one brief, visuals,
-- ad copy, and measurement -- with the consistency argument as the core benefit.
-- Funnels to WSQ Generative AI for Social Media Marketing (TGS-2021003023), SG-only.
-- Published live (status=1), BACK-DATED to 2025-05-27 per the admin's "date all the digital
-- marketing blogs in Apr to Aug 2025" (post 7 of 16, WSQ/CASL digital marketing batch).
--
-- BACK-DATED => linkedin_urn / facebook_post_id = 'manual-skip' so publishDue's share
-- step permanently no-ops (standing rule, blog-pipeline SKILL.md "Hard-won rules").
--
-- All external + course URLs verified HTTP 200 on 2026-09-07.
--
-- NOTE: hero_image_url is NULL here by design -- generate the hero ON PROD after
-- deploy. Hero artwork string (NOT the stored title, which would mis-theme):
--   artwork: Generative AI for Social Media Marketing: Plan, Create, Measure
--   kicker:  Social Media

-- @mms_instance is pre-set by apply.php from MMS_COUNTRY_CODE (defaults to 'SG').
SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO mmd_blog_post
  (title, url_key, excerpt, content, author, status, published_at, related_skus, source_sku,
